--- db/schema.ts
+++ db/schema.ts
+import { schema, table, t } from "okmodel/pg";
+
+// Example table. Delete `users` and take it out of `tables` when you add your own.
+// Requires PostgreSQL 15 or newer (minPostgres: 15).
+
+export const users = table("users", {
+  id: t.id(),
+  email: t.text(),
+  createdAt: t.timestamptz(),
+});
+
+export const app = schema({
+  minPostgres: 15,
+  tables: [users],
+});
+
+declare module "okmodel" {
+  interface Register {
+    readonly schema: typeof app;
+  }
+}

--- db/client.ts
+++ db/client.ts
+import { connect } from "okmodel/pg/postgresjs";
+
+import { app } from "./schema.ts";
+
+const url = process.env.DATABASE_URL;
+if (url === undefined || url.length === 0) {
+  throw new Error("DATABASE_URL is not set");
+}
+
+export const db = connect(url, { schema: app });
